<script setup lang="ts">import{computed,ref}from"vue";import type{AuditLogRecord}from"@/domain/providers/records";const props=defineProps<{items:AuditLogRecord[]}>();const query=ref("");const filtered=computed(()=>{const q=query.value.toLocaleLowerCase("pt-PT");return props.items.filter(x=>!q||`${x.entidade} ${x.entidade_nome||""} ${x.acao} ${x.erro||""}`.toLocaleLowerCase("pt-PT").includes(q))});const date=(v:string)=>new Intl.DateTimeFormat("pt-PT",{dateStyle:"short",timeStyle:"medium"}).format(new Date(v));</script><template><section class="panel audit-log-panel" aria-labelledby="audit-log-title"><div class="section-heading"><div><p class="eyebrow">Auditoria</p><h2 id="audit-log-title">Registo de operações</h2></div><label class="form-field"><span>Pesquisar</span><input v-model.trim="query" type="search"/></label></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Entidade</th><th>Ação</th><th>Origem</th><th>Resultado</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td>{{date(item.created)}}</td><td>{{item.entidade_nome||item.entidade}}<small v-if="item.entidade_id">{{item.entidade_id}}</small></td><td>{{item.acao}}</td><td>{{item.origem||'—'}}</td><td><span :class="item.sucesso===false?'status-danger':'status-success'">{{item.sucesso===false?'Falhou':'Sucesso'}}</span><small v-if="item.erro">{{item.erro}}</small></td></tr></tbody></table></div></section></template>
